#!/usr/bin/env node
// Idempotent upsert of a prepared bilingual question set (see
// supabase/seed-data/*.json) into quiz_questions for a given certification
// slug. Idempotency key is `source_ref` (derived from each row's
// `source_id`), so re-running this script after editing the seed file
// updates existing rows instead of duplicating them.
//
// Usage:
//   SUPABASE_URL=... SUPABASE_SERVICE_ROLE_KEY=... \
//     node scripts/import-quiz-questions.mjs <certification-slug> <path-to-seed-json>
//
// The seed JSON is NOT generated by this script - authoring MCQ
// distractors/matching pools from a raw question+answer source is a curation
// step done once (with care, cross-checked against the source) and the
// result is committed under supabase/seed-data/. This script only handles
// the mechanical, safe-to-repeat part: pushing that prepared data to the DB.

import { createClient } from "@supabase/supabase-js";
import { readFile } from "node:fs/promises";

const [, , slug, seedPath] = process.argv;
if (!slug || !seedPath) {
  console.error("Usage: node scripts/import-quiz-questions.mjs <certification-slug> <path-to-seed-json>");
  process.exit(1);
}

const url = process.env.SUPABASE_URL;
const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!url || !serviceKey) {
  console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY must be set.");
  process.exit(1);
}

const supabase = createClient(url, serviceKey);

const rows = JSON.parse(await readFile(seedPath, "utf-8"));

const { data: cert, error: certError } = await supabase
  .from("certifications")
  .select("id")
  .eq("slug", slug)
  .single();
if (certError || !cert) {
  console.error(`Certification not found for slug "${slug}":`, certError?.message);
  process.exit(1);
}

const { data: existing } = await supabase
  .from("quiz_questions")
  .select("position")
  .eq("certification_id", cert.id)
  .order("position", { ascending: false })
  .limit(1);
let nextPosition = (existing?.[0]?.position ?? 0) + 1;

const dbRows = rows.map((r) => {
  const base = {
    certification_id: cert.id,
    source_ref: `${slug}-json-${r.source_id}`,
    type: r.type,
    question: r.question_fr,
    question_en: r.question_en,
    explanation: r.explanation_fr,
    explanation_en: r.explanation_en,
    exam_only: !r.is_free,
  };
  if (r.type === "match") {
    return {
      ...base,
      pool: r.pool_fr,
      pool_en: r.pool_en,
      targets: r.targets.map((t) => ({ label: t.label_fr, correctPoolIndex: t.correctPoolIndex })),
      targets_en: r.targets.map((t) => ({ label: t.label_en, correctPoolIndex: t.correctPoolIndex })),
    };
  }
  return {
    ...base,
    options: r.options_fr,
    options_en: r.options_en,
    correct_indexes: r.correct_indexes,
  };
});

// Existing rows keep their current position (an upsert batch needs a
// uniform column set, and position has no default) - only rows genuinely new
// to this certification get one assigned from the running counter.
const { data: alreadyImported } = await supabase
  .from("quiz_questions")
  .select("source_ref, position")
  .eq("certification_id", cert.id)
  .in("source_ref", dbRows.map((r) => r.source_ref));
const existingPositions = new Map((alreadyImported ?? []).map((r) => [r.source_ref, r.position]));

for (const row of dbRows) {
  row.position = existingPositions.has(row.source_ref)
    ? existingPositions.get(row.source_ref)
    : nextPosition++;
}

const { error: upsertError } = await supabase
  .from("quiz_questions")
  .upsert(dbRows, { onConflict: "source_ref", ignoreDuplicates: false });

if (upsertError) {
  console.error("Upsert failed:", upsertError.message);
  process.exit(1);
}

console.log(`Upserted ${dbRows.length} questions for certification "${slug}" (${dbRows.length - existingPositions.size} new, ${existingPositions.size} updated).`);
